        return text.strip("'\"")

    if name.endswith("_due_date") or name.startswith("normalize_") or name == "convert_float":
        return None

    if name.startswith("format_"):
        cur = cur_of(args[1])
        return "%s(%s, %s)" % (name, money(args[0], cur), args[1]), None

    if name.endswith("_exceeds") or name.endswith("_settled"):
        return "%s(%s, %s)" % (name, money(args[0], "USD"), money(args[1], "USD")), "True"

    if name.startswith("split_"):
        cur = cur_of(args[-1])
        parts = int(args[1])
        call = "%s(%s, %s, %s)" % (name, money(args[0], cur), args[1], args[-1])
        expected = "[%s] * %d" % (money("2.5", cur), parts)
        return call, expected

    if name.startswith("total_"):
        cur = cur_of(args[1])
        items = split_args(args[0].strip("[]"))
        call = "%s([%s], %s)" % (name, ", ".join(money(a, cur) for a in items), args[1])
        return call, money("6.75", cur)

    if name.startswith(("percent_of_", "net_", "scaled_", "capped_", "accrued_")):
        cur = cur_of(args[-1])
        expected = {"percent_of_": "15", "net_": "180", "scaled_": "15",
                    "capped_": "50", "accrued_": "10"}
        value = next(v for k, v in expected.items() if name.startswith(k))
        if name.startswith(("percent_of_", "net_", "scaled_")):
            call = "%s(%s, Decimal(%s), %s)" % (name, money(args[0], cur), args[1], args[-1])
        elif name.startswith("capped_"):
            call = "%s(%s, Decimal(%s), %s, %s)" % (
                name, money(args[0], cur), args[1], money(args[2], cur), args[-1])
        else:
            call = "%s(%s, Decimal(%s), %s, %s)" % (
                name, money(args[0], cur), args[1], args[2], args[-1])
        return call, money(value, cur)

    if name.startswith(("convert_", "quote_")):
        src, dst = cur_of(args[1]), cur_of(args[2])
        expected = {"convert_": "92.13", "quote_": "91.67"}
        value = next(v for k, v in expected.items() if name.startswith(k))
        call = "%s(%s, %s, %s%s)" % (
            name, money(args[0], src), args[1], args[2],
            "".join(", " + a for a in args[3:]))
        return call, money(value, dst)

    raise AssertionError("unknown family: %s" % name)


def main():
    changed = 0
    for path in sorted((ROOT / "tests").rglob("test_*.py")):
        text = path.read_text(encoding="utf-8")
        out = []
        for line in text.splitlines():
            m = re.match(r"^(\s*)self\.assertEqual\((.*)\)\s*$", line)
            if not m:
                out.append(line)
                continue
            body = m.group(2)
            head = split_call(body)
            expected = body[len(head) + 1:].strip()
            assert head.endswith(")"), head
            hstart = head.index("(")
            name = head[:hstart]
            args = split_args(head[hstart + 1:-1])
            res = transform(name, args)
            if res is None:
                out.append(line)
                continue
            call, new_expected = res
            expected = expected if new_expected is None else new_expected
            out.append("%sself.assertEqual(%s, %s)" % (m.group(1), call, expected))
            changed += 1
        text = "\n".join(out) + ("\n" if text.endswith("\n") else "")
        path.write_text(text, encoding="utf-8")
    print("rewrote", changed, "assertions")


if __name__ == "__main__":
    main()

