"""Tests for ledgerly.tax.vat."""
import datetime
import unittest
from decimal import Decimal

from ledgerly.tax.vat import (
    capped_vat,
    format_vat,
    normalize_vat_ref,
    split_vat,
    total_vat,
    vat_due_date,
    vat_exceeds,
)
from ledgerly.money import Money


class TestTaxVat(unittest.TestCase):
    def test_format_vat(self):
        self.assertEqual(format_vat(Money("2.50", "USD"), 'USD'), '2.50 USD')

    def test_capped_vat(self):
        self.assertEqual(capped_vat(Money("1000.00", "USD"), Decimal("10.0"), Money("50.00", "USD"), 'USD'), Money("50.00", "USD"))

    def test_vat_exceeds(self):
        self.assertEqual(vat_exceeds(Money("10.00", "USD"), Money("5.00", "USD")), True)

    def test_total_vat(self):
        self.assertEqual(total_vat([Money("1.25", "USD"), Money("2.50", "USD"), Money("3.00", "USD")], 'USD'), Money("6.75", "USD"))

    def test_split_vat(self):
        self.assertEqual(split_vat(Money("10.00", "USD"), 4, 'USD'), [Money("2.50", "USD")] * 4)

    def test_normalize_vat_ref(self):
        self.assertEqual(normalize_vat_ref("  ab_12 cd "), "AB-12-CD")

    def test_vat_due_date(self):
        self.assertEqual(vat_due_date(datetime.date(2026, 10, 30), 1), datetime.date(2026, 11, 2))


if __name__ == "__main__":
    unittest.main()
