from pathlib import Path

MODES = {"invoices": "ROUND_HALF_UP", "billing": "ROUND_HALF_UP", "tax": "ROUND_HALF_UP",
         "fx": "ROUND_HALF_EVEN", "interest": "ROUND_HALF_EVEN", "refunds": "ROUND_DOWN",
