print("== rounding modes ==")
for pkg, mode in MODES.items():
    for p in sorted((Path("ledgerly") / pkg).glob("*.py")):
        if p.name == "__init__.py":
            continue
        used = set(re.findall(r"ROUND_[A-Z_]+", p.read_text()))
        if used and used != {mode}:
            print("WRONG MODE", p, used, "expected", mode)
print("done")

print("== unused imports ==")
for p in sorted(Path(".").rglob("*.py")):
    if ".git" in p.parts:
        continue
    src = p.read_text()
    tree = ast.parse(src)
    used = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)}
    used |= {n.attr for n in ast.walk(tree) if isinstance(n, ast.Attribute)}
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for a in node.names:
                name = (a.asname or a.name).split(".")[0]
                if name not in used:
                    print("unused", p, name)
        elif isinstance(node, ast.ImportFrom):
            for a in node.names:
                name = a.asname or a.name
                if name not in used:
                    print("unused", p, name)
print("done")
