"""Tests for ledgerly.fx.quotes."""
import datetime
import unittest
from decimal import Decimal

from ledgerly.money import Money
from ledgerly.fx.quotes import (
    accrued_quote,
    convert_quote,
    normalize_quote_ref,
    quote_due_date,
    quote_exceeds,
    quote_quote,
    split_quote,
)


class TestFxQuotes(unittest.TestCase):
    def test_convert_quote(self):
        self.assertEqual(convert_quote(Money("100.00", "USD"), 'USD', 'EUR'), Money("92.13", "EUR"))

    def test_quote_quote(self):
        self.assertEqual(quote_quote(Money("100.00", "USD"), 'USD', 'EUR', 50), Money("91.67", "EUR"))

    def test_quote_exceeds(self):
        self.assertEqual(quote_exceeds(Money("10.00", "USD"), Money("5.00", "USD")), True)

    def test_accrued_quote(self):
        self.assertEqual(accrued_quote(Money("36500.00", "USD"), Decimal("10.0"), 1, 'USD'), Money("10.00", "USD"))

    def test_split_quote(self):
        self.assertEqual(split_quote(Money("10.00", "USD"), 4, 'USD'), [Money("2.50", "USD")] * 4)

    def test_normalize_quote_ref(self):
        self.assertEqual(normalize_quote_ref("  ab_12 cd "), "AB-12-CD")

    def test_quote_due_date(self):
        self.assertEqual(quote_due_date(datetime.date(2026, 10, 30), 1), datetime.date(2026, 11, 2))


if __name__ == "__main__":
    unittest.main()
"""Tests for ledgerly.export.json_export."""
import datetime
import unittest

from ledgerly.money import Money
from ledgerly.export.json_export import (
    format_json,
    invoice_json,
    json_due_date,
    normalize_json_ref,
    total_json,
)


class TestExportJsonExport(unittest.TestCase):
    def test_invoice_json(self):
        self.assertEqual(invoice_json([('A-1', Money("10.00", "USD")), ('B-2', Money("2.50", "USD"))], 'USD'), '{"currency":"USD","lines":[{"sku":"A-1","amount":{"amount":"10.00","currency":"USD"}},{"sku":"B-2","amount":{"amount":"2.50","currency":"USD"}}],"total":{"amount":"12.50","currency":"USD"}}')

    def test_format_json(self):
        self.assertEqual(format_json(Money("2.50", "USD"), 'USD'), '2.50 USD')

    def test_total_json(self):
        self.assertEqual(total_json([Money("1.25", "USD"), Money("2.50", "USD"), Money("3.00", "USD")], 'USD'), Money("6.75", "USD"))

    def test_normalize_json_ref(self):
        self.assertEqual(normalize_json_ref("  ab_12 cd "), "AB-12-CD")

    def test_json_due_date(self):
        self.assertEqual(json_due_date(datetime.date(2026, 10, 30), 1), datetime.date(2026, 11, 2))


if __name__ == "__main__":
    unittest.main()
