import datetime
import importlib
import inspect
from decimal import Decimal
from pathlib import Path

from ledgerly.money import Money

pkgs = ["invoices", "billing", "tax", "fx", "interest", "refunds", "payouts", "reports", "export"]
count = 0
for pkg in pkgs:
    for path in sorted((Path("ledgerly") / pkg).glob("*.py")):
        if path.name == "__init__.py":
            continue
        mod = importlib.import_module("ledgerly.%s.%s" % (pkg, path.stem))
        for name, fn in vars(mod).items():
            if not inspect.isfunction(fn) or fn.__module__ != mod.__name__:
                continue
            a = Money("10.05", "USD")
            b = Money("2.50", "USD")
            if name.startswith("normalize_"):
                assert fn("  ab_12 cd ") == "AB-12-CD", name
            elif name.endswith("_due_date"):
                assert fn(datetime.date(2026, 10, 30), 1) == datetime.date(2026, 11, 2), name
            elif name.endswith("_exceeds"):
                assert fn(a, b) is True and fn(b, a) is False, name
            elif name.endswith("_settled"):
                assert fn(a, a) is True and fn(a, b) is False, name
            elif name.startswith("format_"):
                r = fn(Money("12.345", "USD"), "USD")
                assert r.split(" ")[0] in ("12.34", "12.35") and r.endswith(" USD"), (name, r)
            elif name.startswith("split_"):
                r = fn(Money("10.00", "USD"), 3, "USD")
                assert len(r) == 3 and all(isinstance(x, Money) for x in r), (name, r)
                assert Money.sum(r, "USD") == Money("10.00", "USD"), (name, r)
                assert fn(Money("10.00", "USD"), 1, "USD") == [Money("10.00", "USD")], name
            elif name.startswith("total_"):
                assert fn([], "USD") == Money("0.00", "USD"), name
                assert fn([], "JPY") == Money("0", "JPY"), name
                assert fn([a, b], "USD") == Money("12.55", "USD"), name
            elif name.startswith("capped_"):
                assert fn(Money("1000.00", "USD"), Decimal("10"), Money("50.00", "USD"), "USD") == Money("100.00", "USD"), name
            elif name.startswith("percent_of_"):
                assert fn(a, Decimal("50"), "USD") in (Money("5.02", "USD"), Money("5.03", "USD")), name
            elif name.startswith("net_"):
                assert fn(Money("10.00", "USD"), Decimal("10"), "USD") == Money("9.00", "USD"), name
            elif name.startswith("scaled_"):
                assert fn(a, Decimal("2"), "USD") == Money("20.10", "USD"), name
            elif name.startswith("accrued_"):
                assert fn(Money("36500.00", "USD"), Decimal("10"), 1, "USD") == Money("10.00", "USD"), name
                assert fn(Money("36500.00", "USD"), Decimal("10"), 0, "USD") == Money("0.00", "USD"), name
            elif name.startswith("convert_"):
                assert fn(Money("100.00", "USD"), "USD", "EUR") == Money("92.13", "EUR"), name
            elif name.startswith("quote_"):
                assert fn(Money("100.00", "USD"), "USD", "EUR", 50) == Money("91.67", "EUR"), name
            elif name == "ledger_csv":
                assert fn([("2026-10-01", "rent", Money("1200.5", "USD"))], "USD") == "date,memo,amount,currency\n2026-10-01,rent,1200.50,USD\n", name
            elif name == "invoice_json":
                assert fn([], "USD") == '{"currency":"USD","lines":[],"total":{"amount":"0.00","currency":"USD"}}', name
            elif name == "convert_float":
                assert fn(100.0, "USD", "EUR") == 92.13
            else:
                raise AssertionError("unclassified %s.%s" % (path.stem, name))
            count += 1
print("checked", count, "functions")
